mapper.select:
SELECT * FROM ( SELECT ROWNUM rnum, temp.* FROM ( SELECT c.class_code AS classCode, c.name AS className, c.status AS classStatus, c.approval_status AS classApprovalStatus, CASE WHEN c.old_address IS NULL OR c.old_address = '-' THEN '' ELSE NVL(REGEXP_SUBSTR(c.old_address, '^.+?[동|구|면|리]'), c.old_address) END AS classRegion, ci.image AS classImg, TO_CHAR(c.price, 'FM999,999,999') || '원' AS classPrice FROM bookmark b JOIN class c ON b.class_code = c.class_code JOIN category cat ON c.category_code = cat.category_code LEFT JOIN category pcat ON cat.parents_category = pcat.category_code LEFT JOIN class_img ci ON c.class_code = ci.class_code AND ci.type = '대표' AND ci.sort_order = 1 WHERE b.member_code = TO_NUMBER(#{memberCode})
AND (cat.name = #{rDTO.filed} OR pcat.name = #{rDTO.filed})
ORDER BY b.bookmark_date DESC ) temp ) WHERE rnum BETWEEN #{rDTO.startNum} AND #{rDTO.endNum}
